let saved;try{saved=new Set((v=>Array.isArray(v)?v.filter(id=>items.some(i=>i.id===id)):['shoulder'])(JSON.parse(localStorage.getItem('sanliang-saved')||'["shoulder"]')));}catch{saved=new Set(['shoulder']);}
let query='',category='',sort='default',collection=false;
const $=s=>document.querySelector(s);const toast=message=>{const t=$('.toast');t.textContent=message;t.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),2400);};
function render(){let visible=items.filter(i=>(!collection||saved.has(i.id))&&(!category||category==='bag')&&(!query||`${i.brand} ${i.brand==='CHANEL'?'香奈儿':'路易威登 LV'} 复古皮革手提包 中古包包`.toLowerCase().includes(query.toLowerCase())));if(sort==='new')visible.reverse();$('#left').innerHTML='';$('#right').innerHTML='';visible.forEach((i,n)=>{const card=document.createElement('article');card.className='card '+(i.height==='tall'?'tall':'');card.dataset.id=i.id;card.tabIndex=0;card.setAttribute('aria-label',i.brand+'复古皮革手提包，17680元');card.innerHTML=`<div class="product-image"><img src="assets/${i.image}.png" alt="${i.brand}复古皮革手提包"></div><span class="condition"><span class="condition-number">98</span><span class="condition-text">新</span></span><button class="heart" aria-label="收藏${i.brand}手提包" aria-pressed="${saved.has(i.id)}"><img src="assets/${saved.has(i.id)?'heart-filled':'heart-outline'}.svg" alt=""></button><p class="eyebrow">VINTAGE · 手提包</p><h2>复古皮革手提包</h2><p class="meta">2004年 · 二手</p><p class="price"><small>￥</small>17680</p>`;card.querySelector('.heart').onclick=e=>{e.stopPropagation();toggle(i.id);};const open=()=>{try{sessionStorage.setItem('sanliang-home-return',JSON.stringify({query,category,sort,collection,scroll:window.scrollY}));}catch{}location.href='product.html?id='+encodeURIComponent(i.id);};card.onclick=open;card.onkeydown=e=>{if(e.target===card&&(e.key==='Enter'||e.key===' ')){e.preventDefault();open();}};$(n%2?'#right':'#left').append(card);});$('.empty').hidden=visible.length>0;document.querySelectorAll('.product-image>img').forEach(img=>img.addEventListener('error',()=>img.classList.add('image-failed'),{once:true}));}
function toggle(id){const target=document.activeElement?.closest('.card')?.dataset.id;saved.has(id)?saved.delete(id):saved.add(id);try{localStorage.setItem('sanliang-saved',JSON.stringify([...saved]));}catch{}render();if(target){const el=document.querySelector('.card[data-id="'+target+'"] .heart');(el||document.querySelector('[data-nav="saved"]')).focus();}}
$('.search').onsubmit=e=>{e.preventDefault();query=$('.search input').value.trim();render();$('#products').scrollIntoView({behavior:'smooth'});};$('.search input').oninput=e=>{query=e.target.value.trim();render();};$('.notice').onclick=()=>toast('暂无新消息');$('#shop').onclick=()=>$('#products').scrollIntoView({behavior:'smooth'});
document.querySelectorAll('.editorial button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.editorial button').forEach(t=>{t.classList.toggle('active',t===b);t.setAttribute('aria-selected',t===b);});toast(b.textContent==='精选'?'正在浏览精选商品':'当前预览仅包含精选商品');});
document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=category===b.dataset.category?'':b.dataset.category;document.querySelectorAll('[data-category]').forEach(c=>c.classList.toggle('selected',c.dataset.category===category));render();});
document.querySelectorAll('[data-sort]').forEach(b=>b.onclick=()=>{sort=b.dataset.sort;document.querySelectorAll('[data-sort]').forEach(c=>c.classList.toggle('active',c===b));render();if(sort==='price')toast('当前商品价格均为 ￥17680');if(sort==='sales')toast('设计稿未提供销量，保留原顺序');});
document.querySelectorAll('[data-brand]').forEach(b=>b.onclick=()=>toast(b.dataset.brand+' 品牌精选，当前为首页预览'));
document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{if(b.dataset.nav==='profile'){location.href='profile.html';return;}if(!['home','saved'].includes(b.dataset.nav)){toast('当前设计稿仅提供首页，此入口暂未接入');return;}collection=b.dataset.nav==='saved';document.querySelectorAll('[data-nav]').forEach(c=>c.classList.toggle('active',c===b));query='';category='';$('.search input').value='';document.querySelectorAll('[data-category]').forEach(c=>c.classList.remove('selected'));render();if(collection)$('#products').scrollIntoView({behavior:'smooth'});else window.scrollTo({top:0,behavior:'smooth'});});
render();

